import React, { useState, useEffect, useRef } from 'react';
import { Send, X, User, Clock, AlertCircle, Paperclip, Smile, MoreVertical } from 'lucide-react';

const ChatWindow = ({ 
  conversation, 
  messages, 
  loading, 
  onSendMessage, 
  onClose,
  isAdmin,
  user 
}) => {
  const [inputMessage, setInputMessage] = useState('');
  const [sending, setSending] = useState(false);
  const messagesEndRef = useRef(null);

  // Fonction pour obtenir le nom de l'autre utilisateur
  const getOtherUserName = () => {
    if (isAdmin) {
      // Pour les admins: afficher le nom de l'utilisateur
      return `${conversation.user_first_name || ''} ${conversation.user_last_name || ''}`.trim() || 'Utilisateur';
    } else {
      // Pour les utilisateurs: afficher le nom de l'admin
      return `${conversation.admin_first_name || ''} ${conversation.admin_last_name || ''}`.trim() || 'Conseiller';
    }
  };

  // Fonction pour obtenir l'email de l'autre utilisateur (pour les admins)
  const getOtherUserEmail = () => {
    if (isAdmin) {
      return conversation.user_email || conversation.email || '';
    }
    return '';
  };

  // Fonction pour obtenir les initiales
  const getInitials = (name) => {
    if (!name) return '?';
    const names = name.split(' ');
    if (names.length >= 2) {
      return (names[0].charAt(0) + names[1].charAt(0)).toUpperCase();
    }
    return name.charAt(0).toUpperCase();
  };

  // Fonction pour envoyer un message
  const handleSend = async () => {
    if (!inputMessage.trim() || sending) return;

    try {
      setSending(true);
      await onSendMessage(conversation.id, inputMessage.trim());
      setInputMessage('');
    } catch (error) {
      console.error('Erreur envoi message:', error);
    } finally {
      setSending(false);
    }
  };

  // Fonction pour gérer la touche Entrée
  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  // Fonction pour scroller vers le bas
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  // Fonction pour formater l'heure
  const formatTime = (dateString) => {
    try {
      const date = new Date(dateString);
      return date.toLocaleTimeString('fr-FR', { 
        hour: '2-digit', 
        minute: '2-digit' 
      });
    } catch {
      return '--:--';
    }
  };

  // Fonction pour formater la date complète
  const formatDate = (dateString) => {
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('fr-FR', { 
        day: 'numeric', 
        month: 'long', 
        year: 'numeric' 
      });
    } catch {
      return '';
    }
  };

  // Scroller vers le bas quand les messages changent
  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Vérifier si un message est lisible
  const isMessageValid = (message) => {
    return message && message.id && message.content;
  };

  // Vérifier si un message est de l'utilisateur courant
  const isCurrentUserMessage = (message) => {
    return message.sender_id === user.id;
  };

  return (
    <div className="bg-gradient-to-br from-white to-white/95 dark:from-neutral-900 dark:to-neutral-900/95 rounded-2xl shadow-2xl border border-white/30 dark:border-neutral-800/50 h-[600px] flex flex-col overflow-hidden">

      {/* Header */}
      <div className="p-4 sm:p-5 border-b border-neutral-200/50 dark:border-neutral-800/50 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-sm">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="relative">
              <div className="h-10 w-10 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center text-white font-bold shadow-lg">
                {getInitials(getOtherUserName())}
              </div>
              <div className="absolute -bottom-1 -right-1 h-3 w-3 rounded-full bg-green-500 border-2 border-white dark:border-neutral-900"></div>
            </div>
            <div>
              <h3 className="font-bold text-lg text-neutral-900 dark:text-white">
                {getOtherUserName()}
              </h3>
              <div className="flex items-center gap-2 mt-0.5">
                <div className="flex items-center gap-1">
                  <div className="h-2 w-2 rounded-full bg-green-500"></div>
                  <span className="text-xs text-neutral-500 dark:text-neutral-400">En ligne</span>
                </div>
                {getOtherUserEmail() && (
                  <>
                    <span className="text-neutral-300 dark:text-neutral-700">•</span>
                    <span className="text-xs text-neutral-500 dark:text-neutral-400 truncate max-w-[120px]">
                      {getOtherUserEmail()}
                    </span>
                  </>
                )}
              </div>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors"
          >
            <X className="w-5 h-5 text-neutral-500" />
          </button>
        </div>
      </div>

      {/* Zone des messages */}
      <div className="flex-1 overflow-y-auto p-4">
        {loading ? (
          <div className="flex flex-col items-center justify-center h-full">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500 mb-3"></div>
            <p className="text-neutral-500">Chargement des messages...</p>
          </div>
        ) : !messages || messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center p-6">
            <div className="h-16 w-16 rounded-xl bg-gradient-to-r from-primary-500/10 to-secondary-500/10 flex items-center justify-center mx-auto mb-4">
              <MessageSquare className="h-8 w-8 text-primary-500/50" />
            </div>
            <h3 className="text-lg font-semibold text-neutral-900 dark:text-white mb-2">
              Aucun message
            </h3>
            <p className="text-sm text-neutral-500 dark:text-neutral-400 max-w-xs mx-auto">
              Commencez la conversation en envoyant votre premier message !
            </p>
          </div>
        ) : (
          <>
            {/* Séparateur de date */}
            {messages.length > 0 && (
              <div className="flex items-center justify-center my-4">
                <div className="h-px flex-1 bg-gradient-to-r from-transparent via-neutral-300/50 dark:via-neutral-700/50 to-transparent"></div>
                <span className="px-3 py-1 text-xs font-medium bg-white/50 dark:bg-neutral-800/50 text-neutral-500 rounded-full mx-2">
                  {formatDate(messages[0]?.created_at)}
                </span>
                <div className="h-px flex-1 bg-gradient-to-r from-transparent via-neutral-300/50 dark:via-neutral-700/50 to-transparent"></div>
              </div>
            )}

            {/* Liste des messages */}
            <div className="space-y-3">
              {messages.map((message) => {
                if (!isMessageValid(message)) return null;

                const isCurrentUser = isCurrentUserMessage(message);

                return (
                  <div
                    key={message.id}
                    className={`flex ${isCurrentUser ? 'justify-end' : 'justify-start'}`}
                  >
                    <div
                      className={`max-w-[85%] rounded-xl p-3 transition-all duration-200 ${
                        isCurrentUser
                          ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none shadow-lg'
                          : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-900 dark:text-white rounded-bl-none'
                      }`}
                    >
                      {/* Contenu du message */}
                      <p className="text-sm leading-relaxed">{message.content}</p>

                      {/* Infos du message */}
                      <div className={`flex items-center justify-between mt-2 ${
                        isCurrentUser ? 'text-white/80' : 'text-neutral-500'
                      }`}>
                        <div className="flex items-center gap-1">
                          <Clock className="w-3 h-3" />
                          <span className="text-xs">{formatTime(message.created_at)}</span>
                        </div>

                        {/* Indicateur de lecture */}
                        {isCurrentUser && message.is_read && (
                          <div className="flex items-center">
                            <CheckCheck className="w-3 h-3" />
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}

              <div ref={messagesEndRef} />
            </div>
          </>
        )}
      </div>

      {/* Zone de saisie */}
      <div className="p-4 border-t border-neutral-200/50 dark:border-neutral-800/50 bg-white/80 dark:bg-neutral-900/80">
        <div className="flex items-center gap-2">
          <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors">
            <Paperclip className="w-5 h-5 text-neutral-500" />
          </button>

          <div className="flex-1">
            <input
              type="text"
              value={inputMessage}
              onChange={(e) => setInputMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder={`Envoyer un message à ${getOtherUserName()}...`}
              className="w-full px-4 py-3 bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              disabled={sending}
            />
          </div>

          <button
            onClick={handleSend}
            disabled={!inputMessage.trim() || sending}
            className="p-3 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg"
          >
            {sending ? (
              <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
            ) : (
              <Send className="w-5 h-5" />
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

